/* Review-site interactions. Every quantitative mark is rendered by Vega/Vega-Lite.
 * JSON definitions and the offline bundle are generated by build_integrated_preview.py.
 */
(() => {
  'use strict';
  const data = window.DV2_PREVIEW;
  const fmt = value => Math.round(value).toLocaleString('en-AU');
  const pct = value => (value * 100).toFixed(1) + '%';
  const el = (tag, className, text) => {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  };
  const clone = value => JSON.parse(JSON.stringify(value));
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const registered = [];
  const allViews = {};
  const errors = [];
  window.DV2Review = {ready: false, views: allViews, registered, errors, data};
  const tooltip = document.getElementById('chart-tooltip');
  function showTooltip(event, value) {
    if (value === null || value === undefined || value === '') { tooltip.hidden = true; return; }
    tooltip.textContent = typeof value === 'object' ? Object.entries(value).map(([key,val]) => key + ': ' + val).join(' · ') : value;
    tooltip.hidden = false;
    tooltip.style.left = Math.max(8, Math.min(event.clientX + 12, innerWidth - 310)) + 'px';
    tooltip.style.top = Math.max(8, Math.min(event.clientY + 12, innerHeight - tooltip.offsetHeight - 10)) + 'px';
  }
  function fail(host, error) {
    errors.push(String(error)); console.error(error);
    host.replaceChildren(el('p', 'chart-error', 'This chart could not load. Its source data and specification are available below.'));
  }
  async function makeView(host, name, options = {}) {
    const spec = clone(options.spec || data.specs[name]);
    host.replaceChildren();
    const view = new vega.View(vega.parse(spec), {renderer: 'svg'}).initialize(host);
    view.tooltip((handler, event, item, value) => showTooltip(event, value));
    const resize = () => {
      const width = Math.max(1, Math.floor(host.getBoundingClientRect().width));
      const height = typeof options.height === 'function' ? options.height(width) : (options.height || spec.height);
      view.width(width).height(height);
      if (options.resize) options.resize(view, width, height);
    };
    if (options.signals) Object.entries(options.signals).forEach(([key,value]) => view.signal(key,value));
    if (options.datasets) Object.entries(options.datasets).forEach(([key,value]) => view.change(key,vega.changeset().remove(() => true).insert(value)));
    resize();
    await view.runAsync();
    const record = {view, host, resize, lastWidth: host.clientWidth};
    registered.push(record);
    if (!allViews[name]) allViews[name] = [];
    allViews[name].push(view);
    return view;
  }
  function lighten(hex) {
    const channels = hex.match(/[a-f\d]{2}/gi).map(x => parseInt(x,16));
    return '#' + channels.map((x,i) => Math.round(x * .6 + [250,249,244][i] * .4).toString(16).padStart(2,'0')).join('');
  }
  function categoryIcon(group) {
    const image = el('img','category-symbol'); image.src = group.iconPath; image.alt = ''; image.width = 24; image.height = 24; image.setAttribute('aria-hidden','true'); return image;
  }
  function readState() {
    try { return JSON.parse(localStorage.getItem('dv2-integrated-review-v1') || '{}'); } catch { return {}; }
  }
  const saved = readState();
  const state = {mode: ['total','production','imports'].includes(saved.mode) ? saved.mode : 'total', selected: null, hovered: null, focused: null, expanded: new Set((saved.expanded || []).filter(n => Number.isInteger(n) && n >= 0 && n < 4)), employmentGroup: null};
  if (Number.isInteger(saved.selected) && state.expanded.has(saved.selected)) state.selected = saved.selected;
  if (data.groups.some(g => g.id === saved.employmentGroup)) state.employmentGroup = saved.employmentGroup;
  window.DV2Review.state = state;
  function persist() {
    try { localStorage.setItem('dv2-integrated-review-v1',JSON.stringify({mode:state.mode,selected:state.selected,expanded:[...state.expanded],employmentGroup:state.employmentGroup})); } catch {}
  }
  function resizeAll() {
    for (const record of registered) {
      const width = record.host.clientWidth;
      if (width > 0 && Math.abs(width - record.lastWidth) > .5) {
        record.lastWidth = width; record.resize(); record.view.runAsync().catch(error => fail(record.host,error));
      }
    }
  }
  async function chapterOne() {
    const root = document.getElementById('dv2-sources-and-value');
    const sources = new Map(), legends = new Map(), rowViews = [], tasks = [];
    const modes = {total:{label:'Total value',basis:'All four groups = 100% of total value',denominator:'production + imports'},production:{label:'Australian production',basis:'All four groups = 100% of production',denominator:'production'},imports:{label:'Imports',basis:'All four groups = 100% of imports',denominator:'imports'}};
    const products = data.products.map(d => ({...d,s:d.p/(d.p+d.i)}));
    const groups = data.groups.map(g => ({...g, s:g.p/(g.p+g.i), full:g.name, children:products.filter(d => d.g===g.g).sort((a,b) => b.s-a.s)}));
    let ring = null, animation = 0, current = [], lastHighlight = null;
    const valuesFor = mode => groups.map(g => mode==='production' ? g.p : mode==='imports' ? g.i : g.p+g.i);
    const announce = text => { root.querySelector('.sv-status').textContent = text; };
    const amounts = d => `${d.full}. Australian production: A$${fmt(d.p)} million (${pct(d.s)}); imports: A$${fmt(d.i)} million (${pct(1-d.s)}); combined: A$${fmt(d.p+d.i)} million.`;
    function syncHighlight() {
      const group = state.hovered ?? state.focused ?? state.selected;
      groups.forEach(d => { const dim = group!==null && group!==d.g; sources.get(d.g).section.dataset.dimmed=String(dim); legends.get(d.g).row.dataset.dimmed=String(dim); });
      const key = `${group}:${state.selected}`;
      if (ring && key !== lastHighlight) { lastHighlight=key; ring.signal('highlightedGroup',group ?? -1).signal('selectedGroup',state.selected ?? -1).runAsync().catch(console.error); }
    }
    function bindHighlight(node, group) {
      node.addEventListener('pointerenter',()=>{state.hovered=group;syncHighlight();});
      node.addEventListener('pointerleave',()=>{if(state.hovered===group)state.hovered=null;syncHighlight();});
      node.addEventListener('focusin',event=>{state.focused=event.target.matches(':focus-visible')?group:null;syncHighlight();});
      node.addEventListener('focusout',event=>{if(!node.contains(event.relatedTarget)){state.focused=null;syncHighlight();}});
    }
    function setExpanded(group, open) {
      const ref = sources.get(group);
      if (open) state.expanded.add(group); else state.expanded.delete(group);
      ref.button.textContent = open ? '−' : '+';
      ref.button.setAttribute('aria-expanded',String(open));
      ref.button.setAttribute('aria-label',(open?'Collapse ':'Expand ')+groups[group].name);
      ref.panel.dataset.open=String(open);ref.panel.setAttribute('aria-hidden',String(!open));ref.panel.inert=!open;
      legends.get(group).button.setAttribute('aria-expanded',String(open));
      root.querySelector('.sv-chocolate-note').hidden=!state.expanded.has(0);
    }
    function choose(group) {
      const open = !state.expanded.has(group);
      if (open) state.selected=group; else if (state.selected===group) state.selected=null;
      setExpanded(group,open);syncHighlight();persist();
      announce(groups[group].name+(open?' expanded. ':' collapsed. ')+'The doughnut still shows all four groups.');
      requestAnimationFrame(resizeAll);
    }
    function makeRowPlot(d, isGroup) {
      const host=el('div','sv-plot');host.dataset.product=isGroup?'group-'+d.g:d.id;host.setAttribute('role','img');host.setAttribute('aria-label',amounts(d));
      tasks.push({host,d,isGroup}); return host;
    }
    groups.forEach(d => {
      const section=el('section','sv-group');section.dataset.group=d.g;section.setAttribute('aria-label',d.name);
      const row=el('div','sv-row sv-summary'), identity=el('div','sv-identity');
      const button=el('button','btn btn-ghost','+');button.type='button';button.id='sv-expand-'+d.g;button.setAttribute('aria-controls','sv-children-'+d.g);
      const icon=el('span','sv-group-icon');icon.append(categoryIcon(d));
      const words=el('div');words.append(el('span','sv-group-name',d.name),el('span','sv-group-count text-small text-muted',d.children.length+' categories'));
      identity.append(button,icon,words);row.append(identity,makeRowPlot(d,true));section.append(row);
      const panel=el('div','sv-expand');panel.id='sv-children-'+d.g;panel.setAttribute('role','region');panel.setAttribute('aria-label',d.name+' product categories');
      const inside=el('div','sv-inside');
      d.children.forEach(child=>{const childRow=el('div','sv-row sv-child');childRow.dataset.productId=child.id;const label=el('div','sv-child-label text-small',child.label);label.title=amounts(child);childRow.append(label,makeRowPlot(child,false));inside.append(childRow);});
      panel.append(inside);section.append(panel);root.querySelector('.sv-groups').append(section);sources.set(d.g,{section,row,button,panel});
      button.addEventListener('click',()=>choose(d.g));identity.addEventListener('click',event=>{if(!button.contains(event.target))button.click();});bindHighlight(section,d.g);
      const legendRow=el('div','sv-legend-row');legendRow.dataset.group=d.g;
      const legendButton=el('button','sv-legend-button');legendButton.type='button';legendButton.setAttribute('aria-controls',panel.id);
      const swatch=el('i','sv-legend-swatch');swatch.style.background=d.color;swatch.setAttribute('aria-hidden','true');
      const content=el('span','sv-legend-content'), name=el('span','sv-legend-name',d.name), metrics=el('span','sv-legend-metrics text-small');
      const amount=el('span','sv-legend-amount'), number=el('span','sv-legend-value tabular-nums'), share=el('span','sv-legend-share tabular-nums');amount.append(number,el('span','text-muted',' A$m'));metrics.append(amount,el('span','text-muted','·'),share);content.append(name,metrics);legendButton.append(swatch,content);legendRow.append(legendButton);root.querySelector('.sv-legend').append(legendRow);legends.set(d.g,{row:legendRow,button:legendButton,value:number,share});legendButton.addEventListener('click',()=>choose(d.g));bindHighlight(legendRow,d.g);
    });
    groups.forEach(d=>setExpanded(d.g,state.expanded.has(d.g)));
    const insightRefs=new Map();
    function takeaway(mode) {
      const v=valuesFor(mode), sum=v.reduce((a,b)=>a+b,0);
      if(mode==='total')return {title:'Similar scale. Different sources.',context:`Food & dairy: A$${(v[0]/1000).toFixed(1)}bn · Clothing: A$${(v[3]/1000).toFixed(1)}bn in total value.`};
      if(mode==='production')return {title:`${pct(v[0]/sum)} of Australian production value comes from food & dairy.`,context:'Across the four selected groups.'};
      return {title:`Clothing accounts for ${pct(v[3]/sum)} of import value.`,context:'Across the four selected groups.'};
    }
    Object.keys(modes).forEach(mode=>{const story=takeaway(mode),panel=el('div','sv-insight-state');panel.dataset.insight=mode;panel.append(el('p','sv-insight-label text-small text-muted','KEY TAKEAWAY · '+mode.toUpperCase()),el('h3','sv-takeaway',story.title),el('p','sv-insight-context text-small text-muted',story.context));root.querySelector('.sv-insights').append(panel);insightRefs.set(mode,panel);});
    function renderValues() {
      const total=current.reduce((a,b)=>a+b,0), meta=modes[state.mode];
      root.querySelector('.sv-center-number').textContent=fmt(total);root.querySelector('.sv-center-number').dataset.total=total;
      root.querySelector('.sv-basis').textContent=meta.basis;
      root.querySelector('.sv-doughnut').setAttribute('aria-label',`${meta.label}, A$${fmt(total)} million across all four groups.`);
      groups.forEach((d,i)=>{const ref=legends.get(d.g);ref.value.textContent=fmt(current[i]);ref.share.textContent=pct(current[i]/total);ref.button.setAttribute('aria-label',`${d.name}: A$${fmt(current[i])} million; ${pct(current[i]/total)} of four-group ${meta.denominator}. Expand or collapse product categories.`);});
      if(ring){ring.change('amounts',vega.changeset().remove(()=>true).insert(groups.map((d,i)=>({g:d.g,name:d.name,color:d.color,value:current[i]})))).signal('amountMode',meta.denominator).runAsync().catch(console.error);}
    }
    function setMode(mode, animate) {
      if(!modes[mode])return;
      cancelAnimationFrame(animation);state.mode=mode;
      root.querySelectorAll('[data-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mode===mode)));
      insightRefs.forEach((panel,key)=>{const active=key===mode;panel.dataset.active=String(active);panel.setAttribute('aria-hidden',String(!active));panel.inert=!active;});
      const to=valuesFor(mode),from=current.length?current.slice():to;
      if(animate&&!reduced.matches){const start=performance.now();const frame=now=>{const t=Math.min(1,(now-start)/460),ease=t*t*(3-2*t);current=from.map((n,i)=>n+(to[i]-n)*ease);renderValues();if(t<1)animation=requestAnimationFrame(frame);else{current=to;renderValues();}};animation=requestAnimationFrame(frame);}
      else{current=to;renderValues();}
      if(animate){persist();announce(modes[mode].label+' shown. The source shares on the left are unchanged.');}
    }
    root.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.mode!==state.mode)setMode(button.dataset.mode,true);}));
    await Promise.all(tasks.map(async ({host,d,isGroup})=>{const view=await makeView(host,'ch1_supply_row',{height:isGroup?60:52,signals:{production:d.p,imports:d.i,groupColor:groups[d.g].color,importColor:lighten(groups[d.g].color),isGroup,label:d.full}});rowViews.push({view,d,isGroup});}));
    await makeView(root.querySelector('.sv-axis'),'ch1_supply_axis',{height:52});
    ring=await makeView(root.querySelector('.sv-doughnut'),'ch1_amount_donut',{height:width=>Math.min(width,320)});
    ring.addEventListener('mouseover',(event,item)=>{if(item?.mark?.name==='slices'){state.hovered=item.datum.g;syncHighlight();}});
    ring.addEventListener('mouseout',(event,item)=>{if(item?.mark?.name==='slices'){state.hovered=null;syncHighlight();}});
    ring.addEventListener('click',(event,item)=>{if(item?.mark?.name==='slices'){choose(item.datum.g);sources.get(item.datum.g).button.focus({preventScroll:true});}});
    const align=()=>groups.forEach(d=>legends.get(d.g).row.style.setProperty('--sv-value-row-height',sources.get(d.g).row.getBoundingClientRect().height+(d.g?1:0)+'px'));
    const observer=new ResizeObserver(align);groups.forEach(d=>observer.observe(sources.get(d.g).row));
    setMode(state.mode,false);syncHighlight();align();window.DV2Review.chapterOne={rowViews,ring,choose,setMode};
  }

  async function chapterTwo() {
    const root=document.getElementById('chapter-2'),overview=root.querySelector('.people-overview'),detail=document.getElementById('people-detail');
    const detailHost=document.getElementById('people-industry-chart');
    let detailView=null,detailCreation=null;
    const pictograms=[];
    const jobs=[];
    data.groups.forEach(group=>{
      const button=el('button','people-group');button.type='button';button.dataset.employmentGroup=group.id;button.setAttribute('aria-controls','people-detail');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label',`${group.name}: ${fmt(group.totals[2])} people employed. Explore ${group.industries.length} related industries.`);
      const label=el('span','people-group-name');label.append(categoryIcon(group),el('span','',group.name+(group.g===1?'*':'')));
      const host=el('span','people-grid-host');host.setAttribute('aria-hidden','true');
      const count=el('span','people-count',fmt(group.totals[2])+' ');count.append(el('small','','people'));
      const action=el('span','people-group-action',`Explore ${group.industries.length} industries +`);
      button.append(label,host,count,action);overview.append(button);
      button.addEventListener('click',()=>selectGroup(state.employmentGroup===group.id?null:group.id,true));
      jobs.push({host,group});
    });
    function niceLimit(maximum) {const target=maximum*1.22,base=10**Math.floor(Math.log10(target));return [1,2,2.5,5,10].map(n=>n*base).find(n=>n>=target);}
    async function selectGroup(id,save=false) {
      state.employmentGroup=id;
      overview.querySelectorAll('button').forEach(button=>{const group=data.groups.find(g=>g.id===button.dataset.employmentGroup),active=id===group.id;button.setAttribute('aria-expanded',String(active));button.querySelector('.people-group-action').textContent=active?'Collapse industries −':`Explore ${group.industries.length} industries +`;});
      detail.hidden=id===null;
      if(id){
        const group=data.groups.find(g=>g.id===id);document.getElementById('people-detail-title').replaceChildren(categoryIcon(group),el('span','',`${group.name} · ${group.industries.length} industries`));
        const signals={groupColor:group.color,limit:niceLimit(Math.max(...group.industries.map(d=>d.current)))};
        if(!detailView){
          if(!detailCreation)detailCreation=makeView(detailHost,'ch2_industry_columns',{height:325,signals,datasets:{industries:group.industries}});
          detailView=await detailCreation;
          if(state.employmentGroup!==id)return;
        }
        detailView.change('industries',vega.changeset().remove(()=>true).insert(group.industries));Object.entries(signals).forEach(([key,value])=>detailView.signal(key,value));detailView.width(Math.floor(detailHost.clientWidth));await detailView.runAsync();
        document.getElementById('people-status').textContent=group.name+' expanded. June 2025 employment by related industry.';
      }
      if(save)persist();
    }
    document.getElementById('people-close').addEventListener('click',()=>{const button=overview.querySelector(`[data-employment-group="${state.employmentGroup}"]`);selectGroup(null,true);button?.focus();});
    await Promise.all(jobs.map(async ({host,group})=>{const count=Math.round(group.totals[2]/1000);const view=await makeView(host,'ch2_employment_pictogram',{height:()=>host.clientHeight,resize:view=>view.signal('columns',innerWidth<=420?6:8),signals:{personCount:group.totals[2],groupName:group.name,iconUrl:group.personUri},datasets:{people:Array.from({length:count},(_,index)=>({index}))}});pictograms.push({group:group.id,view});}));
    const change=await makeView(document.getElementById('people-change-chart'),'ch2_employment_change',{height:width=>width<550?458:438,resize:(view,width)=>view.signal('bottomPad',width<550?132:118)});
    window.DV2Review.chapterTwo={pictograms,change,selectGroup,get detailView(){return detailView;}};
    if(state.employmentGroup)await selectGroup(state.employmentGroup);
  }

  async function legacyChapters() {
    const select=document.getElementById('state-inspector');
    if(select){data.stateRows.forEach(row=>select.add(new Option(row.state_name,row.state_code)));select.addEventListener('change',()=>{const row=data.stateRows.find(r=>r.state_code===select.value);document.getElementById('state-detail').textContent=row?`${row.state_name}: ${row.display_value}. Dairy products processed · 2025 · State of Origin. ${row.value_aud===null?'No record is not a verified zero.':'Recorded nominal export value, FOB; excludes re-exports.'}`:'Choose a state or territory to read its value.';});}
    const definitions=[['dairy-map','ch3_dairy_choropleth'],['logo-attributes','ch4_logo_attributes'],['premium-bands','ch4_premium_bands']];
    await Promise.all(definitions.map(async ([id,name])=>{
      const host=document.getElementById(id);if(!host)return;
      try {
        const spec=clone(data.legacy[name]),narrow=host.clientWidth<540;
        spec.width=Math.floor(host.clientWidth);spec.height=id==='dairy-map'?(narrow?370:540):360;
        if(id==='dairy-map'){spec.layer[0].encoding.color.legend.gradientLength=Math.min(350,spec.width-55);}
        else{spec.config.axisY={...(spec.config.axisY||{}),labelLimit:narrow?125:265,labelFontSize:12};spec.config.axisX={...(spec.config.axisX||{}),labelFontSize:narrow?10:12,titleFontSize:12};}
        const compiled=vegaLite.compile(spec).spec;
        await makeView(host,name,{spec:compiled,height:width=>id==='dairy-map'?(width<540?370:540):360});
      } catch(error){fail(host,error);}
    }));
  }
  async function boot() {
    await chapterOne();
    await chapterTwo();
    await legacyChapters();
    let pending=0;
    const observer=new ResizeObserver(()=>{cancelAnimationFrame(pending);pending=requestAnimationFrame(resizeAll);});
    observer.observe(document.querySelector('.page-frame'));
    window.addEventListener('resize',()=>{cancelAnimationFrame(pending);pending=requestAnimationFrame(resizeAll);});
    window.DV2Review.ready=true;
  }
  boot().catch(error=>{errors.push(String(error));console.error(error);const notice=el('p','chart-error','Some charts could not load: '+error.message);document.querySelector('main').prepend(notice);});
})();
